import { describe, it, expect } from "vitest";
import { resolveProfileSettings } from "@/shared/lib/security/profileEnforcement";
import { findProfile } from "@/shared/lib/security/agentProfiles";

const profile = (id: string) => {
  const p = findProfile(id);
  if (!p) throw new Error(`missing profile ${id}`);
  return p;
};

describe("resolveProfileSettings", () => {
  it("maps allow/deny tool tiers to tool rules (ask is left to prompt)", () => {
    const s = resolveProfileSettings(profile("pf_sandbox"));
    // read/grep/glob allow → allowed tools
    expect(s.allowToolRules).toEqual(expect.arrayContaining(["Read", "Grep", "Glob"]));
    // web/task deny → denied tools
    expect(s.denyToolRules).toEqual(expect.arrayContaining(["WebFetch", "WebSearch", "Task"]));
    // edit/write are "ask" → neither allowed nor denied (Claude prompts)
    expect(s.allowToolRules).not.toContain("Edit");
    expect(s.denyToolRules).not.toContain("Edit");
  });

  it("never blanket-denies Bash (would kill guaranteed gh/git)", () => {
    // pf_sandbox sets bash: "deny" — but Bash must not be denied wholesale.
    const s = resolveProfileSettings(profile("pf_sandbox"));
    expect(s.denyToolRules).not.toContain("Bash");
  });

  it("exposes the bash posture from the profile's bash tier (#1572)", () => {
    // The backend uses this to scale the auto-approve baseline (a bare `Bash` allow isn't
    // honored by Claude Code), rather than a deny rule.
    expect(resolveProfileSettings(profile("pf_auto")).bashPosture).toBe("allow");
    expect(resolveProfileSettings(profile("pf_review")).bashPosture).toBe("ask");
    expect(resolveProfileSettings(profile("pf_sandbox")).bashPosture).toBe("deny");
  });

  it("scopes file-write tools by path globs (deny wins)", () => {
    const s = resolveProfileSettings(profile("pf_sandbox")); // paths.deny: ["**/*"]
    // Path-scoped file rule is Edit(glob) ONLY (#3534) — Edit covers every file-editing tool.
    expect(s.denyToolRules).toContain("Edit(**/*)");
    expect(s.denyToolRules).not.toContain("Write(**/*)");
    expect(s.denyToolRules).not.toContain("MultiEdit(**/*)");
  });

  it("carries the command allowlist + per-glob allows for a trusted profile", () => {
    const s = resolveProfileSettings(profile("pf_auto"));
    expect(s.allowedCommands).toEqual(["cargo", "npm", "pnpm", "pytest", "make", "node", "docker", "gh", "aws"]);
    // whole-tool edit/write tiers (Edit/NotebookEdit/Write — no MultiEdit) + the path rule Edit(**/*).
    expect(s.allowToolRules).toEqual(
      expect.arrayContaining(["Edit", "NotebookEdit", "Write", "Edit(**/*)"]),
    );
    expect(s.allowToolRules).not.toContain("MultiEdit");
    expect(s.allowToolRules).not.toContain("Write(**/*)");
    // paths.deny → denied write globs, Edit(glob) only.
    expect(s.denyToolRules).toEqual(expect.arrayContaining(["Edit(**/.env)", "Edit(**/secrets/**)"]));
  });

  it("denies the edit tools when a profile sets edit/write to deny", () => {
    const s = resolveProfileSettings(profile("pf_review")); // edit:deny, write:deny, task:allow
    expect(s.denyToolRules).toEqual(expect.arrayContaining(["Edit", "NotebookEdit", "Write"]));
    expect(s.denyToolRules).not.toContain("MultiEdit");
    expect(s.allowToolRules).toContain("Task");
  });

  it("dedupes repeated rules", () => {
    const s = resolveProfileSettings(profile("pf_auto")); // paths.allow: ["**/*"]
    const editAll = s.allowToolRules.filter((r) => r === "Edit(**/*)");
    expect(editAll).toHaveLength(1);
  });
});
